<script setup lang="ts">import { computed } from 'vue'; import { RouterLink, useRoute } from 'vue-router'; import { topics } from '../content'; import { useAppStore } from '../stores/app'; const topic = computed(() => topics.find(item => item.id === useRoute().params.id)); const store = useAppStore()</script>
<template><div v-if="topic" class="topic-detail"><div class="topic-intro" :style="{ '--accent': topic.color }"><span class="topic-icon">{{ topic.icon }}</span><p>{{ topic.description }}</p></div><div class="lesson-list"><RouterLink v-for="(lesson, index) in topic.lessons" :key="lesson.id" :to="`/lessons/${lesson.id}`" class="lesson-row"><span class="lesson-index">0{{ index + 1 }}</span><div><h2>{{ lesson.title }}</h2><p>{{ lesson.summary }}</p><small><span class="risk" :class="lesson.risk">{{ lesson.risk === 'high' ? 'Cần chú ý' : lesson.risk === 'medium' ? 'Thực hành' : 'Cơ bản' }}</span> · {{ lesson.minutes }} phút · {{ lesson.steps.length }} bước</small></div><span class="lesson-state">{{ store.completed.includes(lesson.id) ? '✓' : '→' }}</span></RouterLink></div></div><div v-else class="empty">Không tìm thấy chuyên đề.</div></template>
